This action is called from a "Save profile" form. Which two are real problems? (Choose two.)

```ts
'use server'
export async function saveProfile(formData: FormData) {
  const session = await auth()
  if (!session) throw new Error('Unauthorized')
  return db.user.update({
    where: { id: session.user.id },
    data: Object.fromEntries(formData),
  })
}
```

Which version of a "mark item complete" action is safe?

```ts
// Version 1
export async function complete(item: Item) {
  await db.item.update({ where: { id: item.id }, data: { completed: true } })
}
// Version 2
export async function complete(item: Item) {
  const parsed = ItemSchema.parse(item) // zod
  await db.item.update({ where: { id: parsed.id }, data: { completed: true } })
}
// Version 3
export async function complete(itemId: string) {
  const session = await auth()
  if (!session?.user) return
  const item = await db.item.findFirst({ where: { id: itemId, ownerId: session.user.id } })
  if (!item) return
  await db.item.update({ where: { id: item.id }, data: { completed: true } })
}
```
